package com.example.data

import androidx.room.Entity
import androidx.room.PrimaryKey

/**
 * Entity class for Room representing a lottery draw.
 *
 * @param id Unique primary key auto-generated by Room
 * @param gameId Identifier for the lottery game (e.g. "649", "uk659", "euromillions", "ro649plus1", "ro540")
 * @param numbers Numbers drawn stored as comma-separated string (e.g. "1,5,12,33,40,49")
 * @param timestamp Time of the draw in milliseconds since epoch
 * @param extraNumbers Optional bonus / star numbers (e.g. "3,9" or "7")
 * @param isLuckyAi Flag indicating if the draw was generated using the Lucky AI algorithm
 */
@Entity(tableName = "draws")
data class Draw(
    @PrimaryKey(autoGenerate = true)
    val id: Long = 0L,
    val gameId: String,
    val numbers: String,
    val timestamp: Long = System.currentTimeMillis(),
    val extraNumbers: String = "",
    val isLuckyAi: Boolean = false
) {
    /**
     * Parses the comma-separated numbers string into a sorted list of integers.
     * Uses explicit type filtering to prevent any type cast issues.
     */
    fun parsedNumbers(): List<Int> {
        val filtered: String = numbers.filter { char -> char.isDigit() || char == ',' }
        if (filtered.isBlank()) return emptyList()
        return filtered.split(",")
            .mapNotNull { it.trim().toIntOrNull() }
            .sorted()
    }

    /**
     * Parses any extra/bonus numbers (e.g. stars for Euromilion or Joker).
     */
    fun parsedExtraNumbers(): List<Int> {
        val filtered: String = extraNumbers.filter { char -> char.isDigit() || char == ',' }
        if (filtered.isBlank()) return emptyList()
        return filtered.split(",")
            .mapNotNull { it.trim().toIntOrNull() }
            .sorted()
    }
}
